<?php require 'config/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT t.*,u.nama,u.fakultas,u.prodi FROM toko t JOIN users u ON u.id=t.user_id WHERE t.user_id=?');$s->execute([$id]);$t=$s->fetch();if(!$t)exit('Toko tidak ditemukan');$q=$pdo->prepare('SELECT * FROM produk WHERE user_id=? ORDER BY created_at DESC');$q->execute([$id]);headpage('Toko');?><div class="panel p-4 mb-3"><h1><?=e($t['nama_toko'])?></h1><p><?=e($t['deskripsi'])?></p><p><?=e($t['nama'])?> · <?=e($t['fakultas'])?> / <?=e($t['prodi'])?></p></div><div class="row g-3"><?php foreach($q as $p):?><div class="col-md-4"><div class="card"><?php if($p['gambar_produk']):?><img src="<?=e($p['gambar_produk'])?>" alt=""><?php endif;?><div class="card-body"><h5><?=e($p['nama_produk'])?></h5><a href="product.php?id=<?=(int)$p['id']?>" class="btn btn-green">Detail</a></div></div></div><?php endforeach;?></div><?php footpage();